import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"サイト専用キーを安全に運用する","description":"","frontmatter":{},"headers":[],"relativePath":"operations/jev-keys.md","filePath":"operations/jev-keys.md","lastUpdated":1793591337000}`),a={name:`operations/jev-keys.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="サイト専用キーを安全に運用する" tabindex="-1">サイト専用キーを安全に運用する <a class="header-anchor" href="#サイト専用キーを安全に運用する" aria-label="Permalink to “サイト専用キーを安全に運用する”">​</a></h1><p>環境の運用者向けの手順です。サイト管理者は<a href="./../guides/jev">管理画面のJev連携</a>を使います。ここで作る<strong>暗号化キー</strong>と、Jevから発行された<strong>APIキー</strong>は別のものです。</p><h2 id="保存方式" tabindex="-1">保存方式 <a class="header-anchor" href="#保存方式" aria-label="Permalink to “保存方式”">​</a></h2><p>APIキーはAES-256-GCMで暗号化して専用テーブルへ保存します。暗号化キーはDBに入れず、Cloudflareの実行時SecretまたはNode.jsの秘密管理機構で保持します。サイトIDと更新版に結び付けて暗号文を検証するため、他サイトへコピーして使うことはできません。</p><p>DBを読めるだけの人から値を保護します。アプリのプロセスと暗号化キーの両方を掌握した運用者まで隔離する仕組みではありません。管理画面には設定有無だけを表示し、キーを復元表示するAPIはありません。</p><h2 id="初回だけ暗号化キーを生成する" tabindex="-1">初回だけ暗号化キーを生成する <a class="header-anchor" href="#初回だけ暗号化キーを生成する" aria-label="Permalink to “初回だけ暗号化キーを生成する”">​</a></h2><p>既にJEV_KEYRINGを設定している環境では、新しい値を上書きしないでください。値を失うと保存済みAPIキーを復号できなくなります。PreviewとProductionには別々の暗号化キーを使います。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev:keyring:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/preview-jev-keyring.json</span></span></code></pre></div><p>暗号化キーを含むJSONファイルを権限0600で作成します。値はターミナルへ表示せず、既存ファイルは上書きしません。<code>data/</code>はGit対象外です。ファイルをGit・チャット・公開成果物へ追加しないでください。Windowsや別のファイルシステムではACLも確認します。</p><h2 id="cloudflare-preview" tabindex="-1">Cloudflare Preview <a class="header-anchor" href="#cloudflare-preview" aria-label="Permalink to “Cloudflare Preview”">​</a></h2><p>まず設定名だけを確認し、JEV_KEYRINGが既にある場合は継続利用します。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-NAME</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>未設定の場合だけ、新しく生成した確認用JSONを標準入力で渡します。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JEV_KEYRING</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-NAME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/preview-jev-keyring.json</span></span></code></pre></div><p>通常のvars、Build変数、共有Previews Baseへ置く方法は使いません。このプロジェクトはBaseを継承しません。Preview自身のSecretは次の配備にも保持されます。続けて<a href="./../getting-started/preview-production">Previewの配備</a>を行い、管理画面の「Jev連携」で暗号化設定の案内が消えることを確認します。</p><h2 id="cloudflare-production" tabindex="-1">Cloudflare Production <a class="header-anchor" href="#cloudflare-production" aria-label="Permalink to “Cloudflare Production”">​</a></h2><p><strong>本番更新が承認されてから</strong>、設定名を確認し、未設定の場合だけ別のファイルを生成・登録します。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev:keyring:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/production-jev-keyring.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JEV_KEYRING</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/production-jev-keyring.json</span></span></code></pre></div><p>上の生成・登録は初回用です。既存のJEV_KEYRINGがある場合は実行せず、鍵の世代更新手順を使います。Secretの変更そのものも実行環境の更新です。確認前にProductionへ実施しないでください。</p><p>各サイトだけでAPIキーを管理するなら、共通JEV_API_KEYは不要です。共通モードのサイトは、共通キーがなければ保留になります。Production配備ではADMIN_TOKENと、JEV_API_KEYまたはJEV_KEYRINGの少なくとも一方が必要です。サイト専用キーを使うにはJEV_KEYRINGが必要です。</p><h2 id="node-js" tabindex="-1">Node.js <a class="header-anchor" href="#node-js" aria-label="Permalink to “Node.js”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev:keyring:create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/node-jev-keyring.json</span></span></code></pre></div><p>実行環境の<code>JEV_KEYRING_FILE</code>へそのファイルの絶対パスを指定し、Node.jsの実行ユーザーだけが読めるようにします。永続化し、DBと別にアクセス制限してバックアップします。秘密管理サービスからJSONを実行時<code>JEV_KEYRING</code>へ渡す方式でも構いません。両方指定した場合はJEV_KEYRINGを優先します。</p><p><code>npm run review</code>は確認用DBに隣接する<code>.jev-keyring.json</code>を初回に自動生成して再利用します。固定判定なので、APIキーを保存しても実Jevへは送りません。</p><h2 id="バックアップと鍵の世代更新" tabindex="-1">バックアップと鍵の世代更新 <a class="header-anchor" href="#バックアップと鍵の世代更新" aria-label="Permalink to “バックアップと鍵の世代更新”">​</a></h2><p>DBのバックアップだけではAPIキーを復元できません。対応する暗号化キーを秘密管理サービスへ別途バックアップし、読める担当者を限定します。Cloudflare Secretは値を後から再取得する機能を前提にしないでください。</p><ol><li>安全な環境で新しい32バイト乱数を生成し、既存JSONのkeysへ新しい世代名で追加する。旧世代の値を保持する。</li><li>activeを新世代へ変え、JEV_KEYRINGを更新する。旧世代はまだ削除しない。</li><li>各サイトで「サイト専用キー」を選んだまま、APIキーを空欄で保存する。現在の値を新世代で再暗号化する。</li><li>全サイトの移行とバックアップの復旧方針を確認してから、不要な旧世代を削除する。必要な過去のバックアップ用の鍵は、別途安全に保持する。</li></ol><p>JSONは<code>active</code>と<code>keys</code>を持ちます。各鍵は32バイトのbase64url（末尾の<code>=</code>なし）、世代名は英数字・アンダースコア・ハイフンで最大40文字、世代数は最大10です。AUTH_SECRETの更新とは独立しています。</p><h2 id="漏洩・紛失・切り戻し" tabindex="-1">漏洩・紛失・切り戻し <a class="header-anchor" href="#漏洩・紛失・切り戻し" aria-label="Permalink to “漏洩・紛失・切り戻し”">​</a></h2><p>APIキーが疑わしい場合はJev側で再発行・失効し、サイトの「Jev連携」から置き換えます。アプリでの削除だけでは提供元のキーは失効しません。</p><p>暗号化キーが漏洩した場合、DBへのアクセス状況も確認し、必要なら保存していた全サイトのAPIキーを提供元で失効・再発行します。暗号化キーを更新するだけで、既に流出した旧暗号文を無効にはできません。</p><p>暗号化キーを失った場合は対応するバックアップから復旧するか、新しい暗号化キーと、各サイトのAPIキーを登録し直します。共通キーへ自動で切り替えて処理を続けることはありません。</p><p>サイト専用キーや利用停止を設定した後に、対応前の古いコードだけへ戻すと共通キーで呼び出すおそれがあります。対応版への修正配備を優先し、切り戻しが必要ならコード・DB・暗号化キーを同じ復旧位置で検討してください。</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};